var i=`cia-triad`;var n=71;var a={en:[{id:`T071-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`CIA Triad`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Zero Trust treats network location as insufficient proof of trust and requires explicit identity, device/workload context and policy for access decisions.`},{id:`B`,text:`The OWASP Top 10 is an awareness list of major web-application risk categories, not a full security checklist.`},{id:`C`,text:`The CIA triad identifies three fundamental security properties: Confidentiality, Integrity and Availability.`},{id:`D`,text:`Supply chain security protects dependencies, build systems, artifacts and publishing workflows from malicious or compromised components.`}]},{id:`T071-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`CIA Triad`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Add security requirements and abuse cases before coding, automate dependency and static checks, review threat models at architectural changes, protect release pipelines, and monitor vulnerabilities after deployment.`},{id:`B`,text:`Prefer secret managers and short-lived workload identities, restrict access by environment, avoid logs and repository commits, and plan emergency rotation.`},{id:`C`,text:`Choose primitives by goal: confidentiality, integrity, authenticity or password verification.`},{id:`D`,text:`For confidentiality, restrict who can read sensitive data; for integrity, prevent or detect unauthorized modification; for availability, maintain service through faults and attacks.`}]},{id:`T071-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`CIA Triad`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`},{id:`B`,text:`An internal admin API must verify the calling service and staff permissions even when requests arrive from a private subnet or VPN. Sensitive actions may require additional assurance.`},{id:`C`,text:`A malicious npm dependency could execute in a build pipeline and steal publish credentials. Restrict install hooks, isolate CI secrets and review unexpected dependency changes.`},{id:`D`,text:`A file upload passes through size/type checks, malware scanning, private object storage, signed access URLs and monitoring. None alone should be assumed perfect.`}]},{id:`T071-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`CIA Triad`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Multiple controls sharing the same misconfiguration or credential are not independent.`},{id:`B`,text:`No tool catches every logic bug; noisy scanners need triage.`},{id:`C`,text:`Overly granular policies can become unmanageable; ownership and automation matter.`},{id:`D`,text:`Maximizing one attribute can harm another: strict checks may add latency, broad replication may enlarge exposure.`}]},{id:`T071-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It helps teams translate vague security goals into explicit controls and measurable risks.`}]}]},{id:`T071-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Protecting confidentiality alone is enough to satisfy the CIA triad.`}]}]},{id:`T071-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Prioritize according to asset value, threats and regulatory needs.`}]}]},{id:`T071-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`CIA Triad`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Zero Trust means blocking every internal request regardless of identity.`},{id:`B`,text:`For confidentiality, restrict who can read sensitive data; for integrity, prevent or detect unauthorized modification; for availability, maintain service through faults and attacks.`},{id:`C`,text:`The CIA triad identifies three fundamental security properties: Confidentiality, Integrity and Availability.`},{id:`D`,text:`Integrity and availability are unrelated to information security.`}]},{id:`T071-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`CIA Triad`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`},{id:`B`,text:`Prioritize according to asset value, threats and regulatory needs.`},{id:`C`,text:`Protecting confidentiality alone is enough to satisfy the CIA triad.`},{id:`D`,text:`Rotating a secret does not require updating consumers or revoking the old credential.`}]},{id:`T071-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent for a CIA threat matrix of a booking workflow with assets, attack paths, controls, residual risks and testable verification steps.`},{id:`B`,text:`Have an agent draft permissions for API, worker, CI and operator roles, then test denied access for every unnecessary resource and action.`},{id:`C`,text:`Ask an agent to produce an SSDLC checklist for a new upload feature, assigning evidence and owners to requirements, code review, deployment and monitoring stages.`},{id:`D`,text:`Ask an agent to design a safe upload flow, list independent controls and show what happens when validation, scanning or URL signing fails.`}]},{id:`T071-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which business outcome suffers if a booking record is correct and private but temporarily unavailable?`}]}]},{id:`T071-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`CIA Triad`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T071-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`,b:!0},{t:` — propose three checks for `},{t:`CIA Triad`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T071-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T071-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`CIA Triad`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`In a hotel PMS, guest contact details need access control and encryption; payment records need integrity checks and audit; bookings need backups and recovery to remain available.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T071-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Тріада CIA`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Zero Trust не вважає розташування в мережі достатнім доказом довіри й вимагає ідентичності, контексту пристрою/навантаження та політики доступу.`},{id:`B`,text:`OWASP Top 10 — огляд основних категорій ризиків вебзастосунків, а не повний контрольний список безпеки.`},{id:`C`,text:`Тріада CIA охоплює три базові властивості безпеки: конфіденційність, цілісність і доступність.`},{id:`D`,text:`Безпека supply chain захищає залежності, систему збірки, артефакти й публікацію від шкідливих компонентів.`}]},{id:`T071-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Тріада CIA`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Додавайте вимоги безпеки й abuse cases до коду, автоматизуйте перевірки залежностей і статичний аналіз, оновлюйте модель загроз при зміні архітектури, захищайте релізи та слідкуйте за вразливостями після деплою.`},{id:`B`,text:`Використовуйте secret manager і короткоживучі workload identities, розмежовуйте середовища, не допускайте секретів у логах і Git та плануйте термінову ротацію.`},{id:`C`,text:`Обирайте примітив за метою: конфіденційність, цілісність, автентичність або перевірка пароля.`},{id:`D`,text:`Для конфіденційності обмежте доступ до чутливих даних; для цілісності запобігайте несанкціонованій зміні та виявляйте її; для доступності забезпечте роботу під час збоїв і атак.`}]},{id:`T071-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Тріада CIA`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`},{id:`B`,text:`Внутрішнє адмін-API має перевіряти сервіс і права працівника навіть у приватній мережі чи VPN. Для чутливих дій може бути потрібне додаткове підтвердження.`},{id:`C`,text:`Шкідливий npm-пакет може виконатися під час збірки й викрасти ключі публікації. Обмежуйте install hooks, ізолюйте CI-секрети й перевіряйте несподівані зміни залежностей.`},{id:`D`,text:`Завантажений файл проходить перевірку типу й розміру, сканування на malware, приватне object storage, підписані URL і моніторинг. Жоден із шарів не вважається бездоганним.`}]},{id:`T071-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Тріада CIA`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Кілька контролів із тим самим неправильним налаштуванням або ключем не є незалежними.`},{id:`B`,text:`Жоден інструмент не ловить усі логічні помилки; шум сканерів потребує triage.`},{id:`C`,text:`Надмірно дрібні політики важко супроводжувати; потрібні власники й автоматизація.`},{id:`D`,text:`Максимізація однієї властивості може шкодити іншій: суворі перевірки додають затримку, а широка реплікація збільшує поверхню витоку.`}]},{id:`T071-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Вона допомагає перетворити загальне «має бути безпечно» на конкретні захисти та ризики.`}]}]},{id:`T071-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Захист лише конфіденційності достатній для тріади CIA.`}]}]},{id:`T071-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Пріоритезуйте за цінністю даних, загрозами та вимогами.`}]}]},{id:`T071-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Тріада CIA`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Zero Trust означає блокувати кожен внутрішній запит незалежно від ідентичності.`},{id:`B`,text:`Для конфіденційності обмежте доступ до чутливих даних; для цілісності запобігайте несанкціонованій зміні та виявляйте її; для доступності забезпечте роботу під час збоїв і атак.`},{id:`C`,text:`Тріада CIA охоплює три базові властивості безпеки: конфіденційність, цілісність і доступність.`},{id:`D`,text:`Цілісність і доступність не мають відношення до інформаційної безпеки.`}]},{id:`T071-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Тріада CIA`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`},{id:`B`,text:`Пріоритезуйте за цінністю даних, загрозами та вимогами.`},{id:`C`,text:`Захист лише конфіденційності достатній для тріади CIA.`},{id:`D`,text:`Ротація секрету не потребує оновлення споживачів чи відкликання старого ключа.`}]},{id:`T071-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента скласти CIA-матрицю загроз для бронювання з активами, сценаріями атак, захистами, залишковими ризиками та тестами.`},{id:`B`,text:`Попросіть агента описати права API, воркера, CI та оператора й протестувати відмову для кожного непотрібного ресурсу й дії.`},{id:`C`,text:`Попросіть агента створити SSDLC-чекліст для upload з доказами й відповідальними на етапах вимог, review, деплою та моніторингу.`},{id:`D`,text:`Попросіть агента спроєктувати безпечний upload, перелічити незалежні контроли й показати поведінку при збої перевірки, сканування або підписання URL.`}]},{id:`T071-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Який бізнес-наслідок має тимчасова недоступність бронювання, навіть якщо воно коректне й приватне?`}]}]},{id:`T071-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Тріада CIA`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T071-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Тріада CIA`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T071-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T071-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Тріада CIA`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`У PMS готелю контактам гостей потрібні контроль доступу та шифрування; платежам — перевірка цілісності й аудит; бронюванням — резервні копії та відновлення.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:71,questions:a};export{o as default,a as questions,i as slug,n as topicId};